changeSet.sql:
DROP INDEX IF EXISTS uq_inventory_item_number_tenant;
CREATE UNIQUE INDEX uq_inventory_item_number_tenant
  ON inventory_item (tenant_code, lower(inventory_number))
  WHERE deleted = false;

DROP INDEX IF EXISTS uq_inventory_item_number;
CREATE UNIQUE INDEX uq_inventory_item_number
  ON inventory_item (lower(inventory_number))
  WHERE deleted = false;
